import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { toast } from 'react-toastify';

// ─── Fixed Quiz Panel ──────────────────────────────────────────────────────
function QuizPanel({ quiz, onPass, onSkip }) {
  const [answers, setAnswers] = useState({});
  const [result, setResult] = useState(null);
  const [submitting, setSubmitting] = useState(false);

  // Safely get questions array
  const questions = quiz?.questions || [];

  const handleSubmit = async () => {
    if (Object.keys(answers).length < questions.length) {
      toast.error('Please answer all questions');
      return;
    }
    setSubmitting(true);

    let correctCount = 0;
    questions.forEach((q, i) => {
      if (answers[i] === q.correctAnswer) correctCount++;
    });

    const score = Math.round((correctCount / questions.length) * 100);
    const passed = score >= (quiz?.passingScore || 70);

    setResult({ score, passed, correct: correctCount, total: questions.length });
    if (passed) toast.success(`Passed! +20 XP`);
    setSubmitting(false);
  };

  // If quiz data is missing, show a fallback
  if (!quiz || questions.length === 0) {
    return (
      <div style={{ padding: '20px', color: '#71717a', textAlign: 'center' }}>
        No quiz questions found for this section.
      </div>
    );
  }

  return (
    <div style={{
      background: '#111113', border: '1px solid rgba(255,255,255,0.08)',
      borderRadius: '16px', padding: '28px', maxWidth: '800px', margin: '20px auto'
    }}>
      <div style={{ marginBottom: '24px' }}>
        <span style={{ fontSize: '11px', color: '#8b5cf6', fontWeight: 600, textTransform: 'uppercase' }}>Quiz</span>
        <h3 style={{ fontSize: '20px', fontWeight: 700 }}>{quiz.title || "Knowledge Check"}</h3>
      </div>

      {!result ? (
        <>
          {questions.map((q, qi) => (
            <div key={qi} style={{ marginBottom: '24px' }}>
              <p style={{ marginBottom: '12px', fontSize: '15px' }}>{qi + 1}. {q.questionText}</p>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                {(q.options || []).map((opt, oi) => (
                  <button 
                    key={oi} 
                    onClick={() => setAnswers(prev => ({ ...prev, [qi]: oi }))}
                    style={{
                      padding: '12px', borderRadius: '8px', textAlign: 'left',
                      background: answers[qi] === oi ? 'rgba(139,92,246,0.2)' : '#18181b',
                      border: `1px solid ${answers[qi] === oi ? '#8b5cf6' : '#27272a'}`,
                      color: answers[qi] === oi ? '#fff' : '#a1a1aa', cursor: 'pointer'
                    }}
                  >
                    {opt}
                  </button>
                ))}
              </div>
            </div>
          ))}
          <button className="btn btn-accent" onClick={handleSubmit} disabled={submitting}>
            {submitting ? 'Checking...' : 'Submit Quiz'}
          </button>
        </>
      ) : (
        <div style={{ textAlign: 'center' }}>
          <h2 style={{ fontSize: '32px', color: result.passed ? '#10b981' : '#f43f5e' }}>{result.score}%</h2>
          <p>{result.passed ? 'Excellent work!' : 'Try reviewing the material again.'}</p>
          <div style={{ marginTop: '20px', display: 'flex', gap: '10px', justifyContent: 'center' }}>
            {result.passed ? (
              <button className="btn btn-primary" onClick={onPass}>Continue to Next Lesson</button>
            ) : (
              <button className="btn btn-ghost" onClick={() => setResult(null)}>Try Again</button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Main Page ──────────────────────────────────────────────────────────────
export default function CoursePlayerPage() {
  const { courseId } = useParams();
  const navigate = useNavigate();
  const [course, setCourse] = useState(null);
  const [activeLesson, setActiveLesson] = useState(null);
  const [activeModule, setActiveModule] = useState(null);
  const videoRef = useRef(null);

  useEffect(() => {
    const fetchCourse = async () => {
      try {
        const { data } = await axios.get(`/api/courses/${courseId}`);
        setCourse(data);
        if (data.modules?.[0]?.content?.[0]) {
          setActiveModule(data.modules[0]);
          setActiveLesson(data.modules[0].content[0]);
        }
      } catch (err) {
        toast.error("Failed to load course");
      }
    };
    fetchCourse();
  }, [courseId]);

  const handleNext = () => {
    const modIdx = course.modules.findIndex(m => m._id === activeModule._id);
    const lesIdx = activeModule.content.findIndex(l => l._id === activeLesson._id);

    if (lesIdx < activeModule.content.length - 1) {
      setActiveLesson(activeModule.content[lesIdx + 1]);
    } else if (modIdx < course.modules.length - 1) {
      const nextMod = course.modules[modIdx + 1];
      setActiveModule(nextMod);
      setActiveLesson(nextMod.content[0]);
    } else {
      toast.success("Course Completed!");
    }
  };

  if (!course) return <div className="p-10">Loading course...</div>;

  return (
    <div style={{ height: '100vh', display: 'flex', flexDirection: 'column', background: '#0a0a0b', color: '#fff' }}>
      {/* Top Header */}
      <div style={{ height: '60px', borderBottom: '1px solid #1f1f23', display: 'flex', alignItems: 'center', padding: '0 20px' }}>
        <button onClick={() => navigate('/dashboard')} style={{ background: 'none', border: 'none', color: '#8b5cf6', cursor: 'pointer' }}>← Back</button>
        <span style={{ marginLeft: '20px', fontWeight: 600 }}>{course.title}</span>
      </div>

      <div style={{ flex: 1, display: 'flex', overflow: 'hidden' }}>
        {/* Left: Content Area */}
        <div style={{ flex: 1, overflowY: 'auto' }}>
          {activeLesson?.type === 'video' ? (
            <div style={{ width: '100%' }}>
              <div style={{ background: '#000', aspectRatio: '16/9' }}>
                <video 
                  key={activeLesson.videoUrl} 
                  controls 
                  style={{ width: '100%', height: '100%' }}
                  src={activeLesson.videoUrl.startsWith('http') ? activeLesson.videoUrl : `http://localhost:5000/${activeLesson.videoUrl}`}
                />
              </div>
              <div style={{ padding: '30px' }}>
                <h1 style={{ fontSize: '24px', fontWeight: 700 }}>{activeLesson.title}</h1>
              </div>
            </div>
          ) : (
            /* This renders if type is 'quiz' */
            <div style={{ padding: '20px' }}>
              <QuizPanel quiz={activeLesson} onPass={handleNext} onSkip={handleNext} />
            </div>
          )}
        </div>

        {/* Right: Sidebar */}
        <div style={{ width: '350px', borderLeft: '1px solid #1f1f23', overflowY: 'auto', background: '#0d0d0f' }}>
          {course.modules?.map((mod, mi) => (
            <div key={mi}>
              <div style={{ padding: '15px', background: '#161618', fontSize: '14px', fontWeight: 600, borderBottom: '1px solid #1f1f23' }}>
                {mi + 1}. {mod.title}
              </div>
              {mod.content?.map((item, ii) => (
                <div 
                  key={ii}
                  onClick={() => { setActiveModule(mod); setActiveLesson(item); }}
                  style={{
                    padding: '12px 20px', cursor: 'pointer', fontSize: '14px',
                    background: activeLesson?._id === item._id ? 'rgba(139,92,246,0.1)' : 'transparent',
                    borderLeft: activeLesson?._id === item._id ? '3px solid #8b5cf6' : '3px solid transparent',
                    display: 'flex', alignItems: 'center', gap: '10px'
                  }}
                >
                  <span>{item.type === 'video' ? '📺' : '📝'}</span>
                  <span style={{ color: activeLesson?._id === item._id ? '#fff' : '#a1a1aa' }}>{item.title}</span>
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
